function bindTranslate(){const src=$('#sourceText'),dst=$('#targetText');src.lang=(state.from==='lv'||state.from==='auto')?'lv':'en';$('#fromLang').onchange=e=>{state.from=e.target.value;src.lang=state.from==='lv'?'lv':state.from==='auto'?'lv':state.from};$('#toLang').onchange=e=>setTarget(e.target.value);$$('[data-target]').forEach(b=>b.onclick=()=>{setTarget(b.dataset.target);render()});src.oninput=()=>{$('#sourceCount').textContent=src.value.length;if(!$('#grammarReview')?.hidden)runLatvianGrammar(src.value)};$('#clearText').onclick=()=>{src.value='';dst.value='';$('#sourceCount').textContent='0';const gr=$('#grammarReview');if(gr)gr.hidden=true};$('#grammarCheck').onclick=()=>runLatvianGrammar(src.value);$('#swapBtn').onclick=()=>{if(state.from==='auto')state.from=state.to;else [state.from,state.to]=[state.to,state.from];render()};$('#provider').value=state.provider;$('#provider').onchange=e=>{state.provider=e.target.value;localStorage.setItem('translate-provider',state.provider)};$('#translateBtn').onclick=async()=>{if(!src.value.trim())return;status('…');try{const j=await translate(src.value,state.from,state.to,state.provider);dst.value=j.translated;status(j.cached?'Cached · 24h':'✓ '+j.provider)}catch(e){status(e.message,true)}};$('#listenBtn').onclick=()=>speak(dst.value,state.to);$('#copyBtn').onclick=()=>navigator.clipboard?.writeText(dst.value);$('#audioBtn').onclick=()=>downloadTts(dst.value,state.to);$('#micText').onclick=()=>oneShotRecognition(state.from,x=>{src.value=x;src.dispatchEvent(new Event('input'))});$('#googleLink').onclick=()=>openExternalModal('google',`https://translate.google.com/?sl=${encodeURIComponent(state.from)}&tl=${encodeURIComponent(state.to)}&text=${encodeURIComponent(src.value)}`);$('#tildeLink').onclick=()=>openExternalModal('tilde','https://tilde.ai/lv/translate/tilde-machine-translation/')}
const LV_WORD_FIXES={
'garumzimes':'garumzīmes','pieturzimes':'pieturzīmes','mikstinajumi':'mīkstinājumi','latviesu':'latviešu','latviesiem':'latviešiem','latviesi':'latvieši','latvija':'Latvija','latvijas':'Latvijas','ludzu':'lūdzu','butu':'būtu','bija':'bija','bus':'būs','mes':'mēs','jus':'jūs','vini':'viņi','vinas':'viņas','vins':'viņš','vina':'viņa','saja':'šajā','sis':'šis','si':'šī','seit':'šeit','sodien':'šodien','rit':'rīt','vel':'vēl','pec':'pēc','pirms':'pirms','kadreiz':'kādreiz','kapec':'kāpēc','tadel':'tādēļ','tapat':'tāpat','tacu':'taču','tomer':'tomēr','svarigi':'svarīgi','pareizi':'pareizi','nepareizi':'nepareizi','vardu':'vārdu','vardi':'vārdi','vards':'vārds','teksta':'tekstā','teksts':'teksts','valoda':'valoda','valodas':'valodas','tulkosana':'tulkošana','tulkot':'tulkot','tulkojums':'tulkojums','ierice':'ierīce','ierices':'ierīces','iespeja':'iespēja','iespejas':'iespējas','izveleties':'izvēlēties','izvele':'izvēle','parbaude':'pārbaude','parbaudit':'pārbaudīt','labot':'labot','kluda':'kļūda','kludas':'kļūdas','rakstit':'rakstīt','rakstiba':'rakstība','pareizrakstiba':'pareizrakstība','teikums':'teikums','teikuma':'teikuma','skaisti':'skaisti','jauks':'jauks','jauku':'jauku','dienu':'dienu','paldies':'paldies','sveiki':'sveiki','atvainojiet':'atvainojiet','iespejams':'iespējams','vispar':'vispār','vairak':'vairāk','mazak':'mazāk','atrak':'ātrāk','lenak':'lēnāk','labs':'labs','labi':'labi','drosi':'droši','vienmer':'vienmēr','ari':'arī','tikai':'tikai','ne':'ne','ja':'ja','jā':'jā','vai':'vai','ka':'ka','kā':'kā','kur':'kur','tur':'tur','nav':'nav','esmu':'esmu','esi':'esi'};
function lvGrammarMatches(text){const out=[];let m;const wordRe=/\b[A-Za-zĀ-ž]+\b/g;while((m=wordRe.exec(text))){const raw=m[0],low=raw.toLocaleLowerCase('lv-LV'),fix=LV_WORD_FIXES[low];if(fix&&fix.toLocaleLowerCase('lv-LV')!==low){let repl=fix;if(raw[0]===raw[0].toUpperCase())repl=repl.charAt(0).toUpperCase()+repl.slice(1);out.push({offset:m.index,length:raw.length,repl,type:'spelling',msg:'Iespējama garumzīmes, mīkstinājuma vai pareizrakstības kļūda.'})}}
 const rules=[
  {re:/\s+([,.;:!?])/g,make:x=>({offset:x.index,length:x[0].length,repl:x[1],type:'punct',msg:'Pirms pieturzīmes parasti neliek atstarpi.'})},
  {re:/([,;:!?])(\S)/g,make:x=>({offset:x.index,length:x[0].length,repl:x[1]+' '+x[2],type:'punct',msg:'Pēc pieturzīmes parasti vajadzīga atstarpe.'})},
  {re:/([!?.,])\1{1,}/g,make:x=>({offset:x.index,length:x[0].length,repl:x[1],type:'punct',msg:'Atkārtota pieturzīme.'})},
  {re:/ {2,}/g,make:x=>({offset:x.index,length:x[0].length,repl:' ',type:'space',msg:'Vairākas atstarpes pēc kārtas.'})}
 ];
 for(const r of rules){r.re.lastIndex=0;while((m=r.re.exec(text)))out.push(r.make(m))}
 const sentRe=/(^|[.!?]\s+)([a-zāčēģīķļņšūž])/g;while((m=sentRe.exec(text))){const pos=m.index+m[1].length;out.push({offset:pos,length:1,repl:m[2].toLocaleUpperCase('lv-LV'),type:'case',msg:'Teikumu parasti sāk ar lielo burtu.'})}
 return out.sort((a,b)=>a.offset-b.offset||a.length-b.length).filter((x,i,a)=>!i||x.offset!==a[i-1].offset||x.length!==a[i-1].length);
}
function grammarMarkedHtml(text,matches){let html='',p=0;for(const x of matches){if(x.offset<p)continue;html+=esc(text.slice(p,x.offset));html+=`<span class="grammar-error" title="${esc(x.msg)}">${esc(text.slice(x.offset,x.offset+x.length))}</span>`;p=x.offset+x.length}return html+esc(text.slice(p)).replace(/\n/g,'<br>')}
function runLatvianGrammar(text){const review=$('#grammarReview'),preview=$('#grammarPreview'),issues=$('#grammarIssues'),note=$('#grammarNote');if(!review||!preview||!issues)return;review.hidden=false;if(!text.trim()){preview.textContent='';issues.innerHTML='<span class="grammar-ok">Ievadiet tekstu pārbaudei.</span>';return}const matches=lvGrammarMatches(text);preview.innerHTML=grammarMarkedHtml(text,matches);if(!matches.length){issues.innerHTML='<span class="grammar-ok">✓ Acīmredzamas kļūdas netika atrastas.</span>';if(note)note.textContent='✓ Latvian check';return}if(note)note.textContent=`${matches.length} iespējam${matches.length===1?'a kļūda':'as kļūdas'}`;issues.innerHTML=matches.slice(0,30).map((x,i)=>`<button class="grammar-fix" data-gfix="${i}"><span>${esc(x.msg)}</span><b>${esc(text.slice(x.offset,x.offset+x.length))} → ${esc(x.repl)}</b></button>`).join('')+`<button class="btn primary grammar-fix-all" id="grammarFixAll">Labot visu</button>`;$$('[data-gfix]').forEach(b=>b.onclick=()=>applyGrammarFix(matches[+b.dataset.gfix]));$('#grammarFixAll').onclick=()=>applyAllGrammarFixes(matches)}
function applyGrammarFix(x){const src=$('#sourceText');if(!src)return;src.value=src.value.slice(0,x.offset)+x.repl+src.value.slice(x.offset+x.length);src.dispatchEvent(new Event('input'))}
function applyAllGrammarFixes(matches){const src=$('#sourceText');if(!src)return;let text=src.value;[...matches].sort((a,b)=>b.offset-a.offset).forEach(x=>{text=text.slice(0,x.offset)+x.repl+text.slice(x.offset+x.length)});src.value=text;src.dispatchEvent(new Event('input'))}

function setTarget(v){state.to=v;localStorage.setItem('translate-target',v)}
function status(s,bad=false){const e=$('#translateStatus');if(e){e.textContent=s;e.classList.toggle('bad',bad)}}
async function translate(text,from,to,provider){const r=await fetch(`${B.apiBase}?action=translate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,from,to,provider})});const j=await r.json().catch(()=>({}));if(!r.ok||!j.ok)throw new Error(j.error||'Translation failed');return j}
function speechLocale(c){return ({lv:'lv-LV',en:'en-GB',ru:'ru-RU',uk:'uk-UA',no:'nb-NO','zh-CN':'zh-CN','zh-TW':'zh-TW'})[c]||c}
const VOICE_GENDER_HINTS={male:['nils','ryan','thomas','guy','henri','conrad','diego','marek','ostap','leonas','kert','jeppe','mattias','finn','harri','dmitry','alvaro','male'],female:['everita','sonia','libby','aria','denise','katja','elsa','zofia','polina','ona','anu','christel','sofie','pernille','noora','svetlana','elvira','female']};
function inferredGender(v){const n=(v.name||'').toLowerCase();if(VOICE_GENDER_HINTS.male.some(x=>n.includes(x)))return'male';if(VOICE_GENDER_HINTS.female.some(x=>n.includes(x)))return'female';return'unknown'}
function voiceScore(v,lang){const n=(v.name||'').toLowerCase(),l=(v.lang||'').toLowerCase(),want=speechLocale(lang).toLowerCase();let s=0;if(l===want)s+=120;else if(l.startsWith(lang.toLowerCase()))s+=80;if(n.includes('natural'))s+=60;if(n.includes('online'))s+=55;if(n.includes('neural'))s+=50;if(n.includes('microsoft'))s+=36;if(n.includes('google'))s+=28;if(n.includes('premium'))s+=24;if(lang==='lv'&&n.includes('nils'))s+=65;if(lang==='lv'&&n.includes('everita'))s+=62;if(state.voiceQuality==='online'&&(n.includes('online')||n.includes('natural')||n.includes('neural')||!v.localService))s+=45;if(state.voiceQuality==='online'&&v.localService)s-=25;if(state.voiceQuality==='local'&&v.localService)s+=50;if(state.voiceQuality==='local'&&!v.localService)s-=80;const g=inferredGender(v);if(state.voiceGender!=='auto'){if(g===state.voiceGender)s+=55;else if(g!=='unknown')s-=45}if(v.default)s+=4;return s}
function voicesFor(lang){return (speechSynthesis.getVoices()||[]).filter(v=>(v.lang||'').toLowerCase().startsWith(lang.toLowerCase())).sort((a,b)=>voiceScore(b,lang)-voiceScore(a,lang))}
function selectedVoice(lang){const list=voicesFor(lang),saved=state.voiceByLang[lang];return list.find(v=>v.name===saved)||list[0]||null}
function voiceLabel(v,i){const g=inferredGender(v),q=/natural|online|neural/i.test(v.name||'')||!v.localService?'HQ':'device',gender=g==='male'?'♂':g==='female'?'♀':'•';return `${i===0?'★ ':''}${gender} ${v.name} (${v.lang}) · ${q}`}
function fillVoiceSelect(){const sel=$('#ttsVoice');if(!sel)return;const list=voicesFor(state.to);sel.innerHTML='<option value="">Automatic best free voice</option>'+list.map((v,i)=>`<option value="${esc(v.name)}">${esc(voiceLabel(v,i))}</option>`).join('');sel.value=state.voiceByLang[state.to]||'';updateVoiceHint()}
function toneSettings(lang){let rate=state.voiceRate||.94,pitch=state.voicePitch||1;if(lang==='lv'){if(state.voiceTone==='warm')rate*=.94;else if(state.voiceTone==='soft')rate*=.96;else if(state.voiceTone==='clear')rate*=.99;pitch=1;return{rate:Math.max(.82,Math.min(1.06,rate)),pitch:1}}if(state.voiceTone==='warm'){rate*=.92;pitch*=.92}else if(state.voiceTone==='soft'){rate*=.94;pitch*=1.04}else if(state.voiceTone==='clear'){rate*=.98;pitch*=1.01}return{rate:Math.max(.72,Math.min(1.22,rate)),pitch:Math.max(.85,Math.min(1.15,pitch))}}
function updateVoiceHint(){const el=$('#voiceHint');if(!el)return;const v=selectedVoice(state.to);if(!v){el.textContent=state.ui==='lv'?'Šajā ierīcē nav atrasta atbilstoša balss. Edge uz Windows/macOS parasti dod vairāk online Natural balsu.':'No matching voice found. Edge on Windows/macOS usually exposes more online Natural voices.';return}const g=inferredGender(v),hq=/natural|online|neural/i.test(v.name||'')||!v.localService;el.textContent=`${state.ui==='lv'?'Izvēlēta':'Selected'}: ${v.name} · ${g==='male'?(state.ui==='lv'?'vīriešu':'male'):g==='female'?(state.ui==='lv'?'sieviešu':'female'):(state.ui==='lv'?'dzimums nav norādīts':'gender unknown')} · ${hq?(state.ui==='lv'?'augstāka kvalitāte / online':'higher quality / online'):(state.ui==='lv'?'ierīces balss':'device voice')}`}
async function speak(text,lang){if(!text.trim())return;const routed=state.audioPan!=='both'||(state.audioOutput&&lang!=='lv');if(routed){try{return await playRoutedTts(text.slice(0,2400),lang)}catch(e){console.warn(e)}}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=speechLocale(lang);const ts=toneSettings(lang);u.rate=ts.rate;u.pitch=ts.pitch;u.volume=+($('#ttsVolume')?.value||.9);const v=selectedVoice(lang);if(v)u.voice=v;speechSynthesis.speak(u)}
async function playRoutedTts(text,lang){const r=await fetch(`${B.apiBase}?action=tts`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,lang})});if(!r.ok)throw new Error('Routed audio unavailable');const blob=await r.blob(),url=URL.createObjectURL(blob),audio=new Audio(url);audio.volume=+($('#ttsVolume')?.value||.9);if(state.audioOutput&&typeof audio.setSinkId==='function')await audio.setSinkId(state.audioOutput);const AC=window.AudioContext||window.webkitAudioContext;if(AC){const ctx=new AC(),src=ctx.createMediaElementSource(audio),pan=ctx.createStereoPanner();pan.pan.value=state.audioPan==='left'?-1:state.audioPan==='right'?1:0;src.connect(pan).connect(ctx.destination);audio.onended=()=>{URL.revokeObjectURL(url);ctx.close().catch(()=>{})};await ctx.resume();await audio.play()}else{audio.onended=()=>URL.revokeObjectURL(url);await audio.play()}}
