function oneShotRecognition(lang,onText){const R=Rec();if(!R)return alert('Speech recognition is not supported in this browser.');const r=new R();r.lang=speechLocale(lang==='auto'?'en':lang);r.interimResults=false;r.onresult=e=>onText(e.results[0][0].transcript);r.start()}
function bindLive(){$('#liveFrom').onchange=e=>state.from=e.target.value;$('#liveTo').onchange=e=>{setTarget(e.target.value);fillVoiceSelect()};const lm=$('#liveMode');if(lm)lm.onchange=e=>{state.liveMode=e.target.value;localStorage.setItem('translate-live-mode',state.liveMode)};$('#liveToggle').onclick=()=>{if(state.listening)stopLive();else{if(state.remoteCapturing)stopRemoteAudio();startLive()}};const testBtn=$('#speechTest');if(testBtn)testBtn.onclick=runSpeechTest;fillVoiceSelect();const vs=$('#ttsVoice');if(vs)vs.onchange=e=>{if(e.target.value)state.voiceByLang[state.to]=e.target.value;else delete state.voiceByLang[state.to];localStorage.setItem('translate-voice-by-lang',JSON.stringify(state.voiceByLang));updateVoiceHint()};const vq=$('#voiceQuality'),vg=$('#voiceGender'),vt=$('#voiceTone'),vr=$('#voiceRate'),vp=$('#voicePitch');if(vq)vq.onchange=e=>{state.voiceQuality=e.target.value;localStorage.setItem('translate-voice-quality',state.voiceQuality);fillVoiceSelect()};if(vg)vg.onchange=e=>{state.voiceGender=e.target.value;localStorage.setItem('translate-voice-gender',state.voiceGender);fillVoiceSelect()};if(vt)vt.onchange=e=>{state.voiceTone=e.target.value;localStorage.setItem('translate-voice-tone',state.voiceTone);updateVoiceHint()};if(vr)vr.oninput=e=>{state.voiceRate=+e.target.value;localStorage.setItem('translate-voice-rate',String(state.voiceRate));$('#voiceRateLabel').textContent=Math.round(state.voiceRate*100)+'%'};if(vp)vp.oninput=e=>{state.voicePitch=+e.target.value;localStorage.setItem('translate-voice-pitch',String(state.voicePitch));$('#voicePitchLabel').textContent=Math.round(state.voicePitch*100)+'%'};const pv=$('#previewVoice');if(pv)pv.onclick=()=>speak(state.to==='lv'?'Labdien! Šī ir izvēlētā latviešu balss. Es runāju skaidri, dabiski un izteiksmīgi.':state.to==='ru'?'Здравствуйте! Это выбранный голос.':'Hello! This is the selected translation voice.',state.to);$('#ttsVolume').oninput=e=>$('#ttsVolLabel').textContent=Math.round(e.target.value*100)+'%';$('#recordBtn').onclick=()=>state.mediaRecorder?.state==='recording'?stopRecording():startRecording();$('#downloadRecord').onclick=()=>state.recordUrl&&downloadUrl(state.recordUrl,`original-recording-${Date.now()}.webm`);$('#downloadTranscript').onclick=()=>{const translated=state.history.map(h=>`[${new Date(h.time).toLocaleString()}]\n${h.original}\n=> ${h.translated}`).join('\n\n');const raw=(state.liveRaw||[]).map(x=>`[${new Date(x.time).toLocaleString()}] ${x.final?'FINAL':'INTERIM'}: ${x.text}`).join('\n');downloadText(`RECOGNIZED SPEECH\n=================\n${raw||'(no recognized speech)'}\n\nTRANSLATIONS\n============\n${translated||'(no translations)'}`,'translation-transcript.txt','text/plain')};$('#downloadLiveAudio').onclick=()=>downloadTts(state.history.slice(-20).map(h=>h.translated).join('. '),state.to);const mediaInput=$('#mediaFile'),mediaDrop=$('#mediaDrop'),mediaChoose=$('#mediaChoose');mediaInput.onchange=e=>loadMedia(e.target.files[0]);const urlInput=$('#mediaUrl'),urlLoad=$('#mediaUrlLoad'),captureBtn=$('#captureTabAudio'),accuracy=$('#mediaAccuracy'),mediaSource=$('#mediaSource');if(mediaSource)mediaSource.onchange=e=>{state.mediaSource=e.target.value;localStorage.setItem('translate-media-source',state.mediaSource);if(state.mediaSource!=='mic'){state.mediaAccuracy='whisper';localStorage.setItem('translate-media-accuracy','whisper');if(accuracy)accuracy.value='whisper'}const h=$('#mediaSourceHelp');if(h)h.textContent=state.mediaSource==='mic'?(state.ui==='lv'?'Mikrofona fallback izmanto Live sadaļu. Video audio netiks ņemts no playera.':'Microphone fallback uses the Live panel. Video audio will not be captured from the player.'):(state.ui==='lv'?'Video/Local režīms analizē pašu media audio ar Whisper; mikrofons netiek izmantots.':'Video/Local mode analyzes the media audio itself with Whisper; the microphone is not used.')};if(accuracy)accuracy.onchange=e=>{state.mediaAccuracy=e.target.value;localStorage.setItem('translate-media-accuracy',state.mediaAccuracy);if(state.mediaSource!=='mic'&&state.mediaAccuracy==='browser'){state.mediaSource='mic';localStorage.setItem('translate-media-source','mic');if(mediaSource)mediaSource.value='mic'}};if(urlLoad)urlLoad.onclick=()=>loadRemoteMedia(urlInput?.value||'');if(urlInput)urlInput.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();loadRemoteMedia(urlInput.value)}};if(captureBtn)captureBtn.onclick=()=>state.remoteCapturing?stopRemoteAudio():captureRemoteAudio();const clearRT=$('#clearRemoteTranscript');if(clearRT)clearRT.onclick=()=>{state.remoteTranscript='';state.remoteInterim='';const rt=$('#remoteTranscript');if(rt)rt.innerHTML='<span class="remote-interim" id="remoteInterim"></span>';};if(mediaChoose)mediaChoose.onclick=e=>{e.stopPropagation();mediaInput.click()};if(mediaDrop){mediaDrop.onclick=e=>{if(e.target===mediaDrop||e.target.classList.contains('upload-title')||e.target.classList.contains('help'))mediaInput.click()};['dragenter','dragover'].forEach(ev=>mediaDrop.addEventListener(ev,e=>{e.preventDefault();mediaDrop.classList.add('drag')}));['dragleave','drop'].forEach(ev=>mediaDrop.addEventListener(ev,e=>{e.preventDefault();mediaDrop.classList.remove('drag')}));mediaDrop.addEventListener('drop',e=>{const f=e.dataTransfer.files[0];if(f)loadMedia(f)})}$('#mediaVolume').oninput=e=>{const m=$('#mediaEl');if(m)m.volume=+e.target.value;$('#mediaVolLabel').textContent=Math.round(e.target.value*100)+'%'};$('#mediaRecognize').onclick=recognizeMedia}
function mergeSpeechFragments(a,b){a=(a||'').trim();b=(b||'').trim();if(!a)return b;if(!b)return a;if(a.toLowerCase().endsWith(b.toLowerCase()))return a;if(b.toLowerCase().startsWith(a.toLowerCase()))return b;const aw=a.split(/\s+/),bw=b.split(/\s+/);let overlap=0;for(let n=Math.min(aw.length,bw.length,8);n>0;n--){const left=aw.slice(-n).join(' ').toLowerCase(),right=bw.slice(0,n).join(' ').toLowerCase();if(left===right){overlap=n;break}}return (a+' '+bw.slice(overlap).join(' ')).replace(/\s+/g,' ').trim()}
