function applyMicProfile(v){state.micProfile=v;const presets={quiet:[1.8,.18,true,true,true],normal:[1.3,.24,true,true,true],noisy:[1.4,.30,true,true,true],headset:[1.2,.22,true,true,true],raw:[1,.16,false,false,false]};const p=presets[v]||presets.normal;[state.micGain,state.micSensitivity,state.micNoise,state.micEcho,state.micAgc]=p;localStorage.setItem('translate-mic-profile',v);localStorage.setItem('translate-mic-gain',state.micGain);localStorage.setItem('translate-mic-sensitivity',state.micSensitivity);localStorage.setItem('translate-mic-noise',state.micNoise?'1':'0');localStorage.setItem('translate-mic-echo',state.micEcho?'1':'0');localStorage.setItem('translate-mic-agc',state.micAgc?'1':'0')}
